<div class="col-md-6"><div class="card"><div class="card-header">Paling banyak klik WhatsApp</div><ul class="list-group list-group-flush"><?php foreach($top_wa as $t): ?><li class="list-group-item d-flex justify-content-between"><?= e($t->nama) ?><b><?= $t->total_wa ?></b></li><?php endforeach; ?></ul></div></div></div>
<script>window.addEventListener('load',function(){var d=<?= json_encode($harian) ?>;new Chart(document.getElementById('ch'),{type:'line',data:{labels:d.map(x=>x.d),datasets:[{label:'Kunjungan',data:d.map(x=>+x.v),borderColor:'#15803d',tension:.3},{label:'Klik WhatsApp',data:d.map(x=>+x.w),borderColor:'#25d366',tension:.3}]}});});</script>
